// Clasifica cada píxel: ala izquierda, ala derecha o cuerpo.
function rgb(c) {
  return [parseInt(c.slice(1, 3), 16), parseInt(c.slice(3, 5), 16), parseInt(c.slice(5, 7), 16)];
}
function es_azul(c) {
  const [r, g, b] = rgb(c);
  return b > r + 15;
}
function es_gris(c) {
  const [r, g, b] = rgb(c);
  return Math.max(r, g, b) - Math.min(r, g, b) < 15;
}
function zona(x, y, c) {
  if (es_azul(c)) return x < 32 ? "ala_izq" : "ala_der";
  if (es_gris(c) && (x <= 21 || x >= 42)) return x < 32 ? "ala_izq" : "ala_der";
  if (es_gris(c) && y >= 29 && y <= 32 && (x <= 23 || x >= 40)) return x < 32 ? "ala_izq" : "ala_der";
  return "cuerpo";
}

// Recorre la receta y pasa a pinta(x, y, c) solo los píxeles de una zona.
function filtra(nombre, pinta) {
  const sp = (x, y, c) => { if (zona(x, y, c) === nombre) pinta(x, y, c); };
  const fr = (x, y, w, h, c) => {
    for (let j = 0; j < h; j++) for (let i = 0; i < w; i++) sp(x + i, y + j, c);
  };
  receta(sp, fr);
}

// Membrana más transparente con tramado: en los frames rápidos se salta un píxel azul de cada dos
// en damero (el borde blanco se queda igual). Así no hacen falta colores nuevos.
function hueco(x, y, c, tramado) {
  return tramado && es_azul(c) && (x + y) % 2 === 0;
}

part("cuerpo", () => {
  filtra("cuerpo", set_pixel);
});

// Ala que gira desde su raíz junto al tórax: giro > 0 la abre hacia delante (abajo),
// giro < 0 la recoge hacia atrás (arriba); escala acorta la envergadura; tramado la vuelve translúcida.
const RAIZ = { ala_izq: [24, 24], ala_der: [39, 24] };
function ala(nombre, { giro = 0, escala = 1, tramado = false } = {}) {
  const [rx, ry] = RAIZ[nombre];
  filtra(nombre, (x, y, c) => {
    if (hueco(x, y, c, tramado)) return;
    const d = Math.abs(x - rx);
    const nx = rx + Math.round((x - rx) * escala);
    const ny = y + Math.round(giro * d);
    set_pixel(nx, ny, c);
  });
}
part("ala_izq", (p) => ala("ala_izq", p));
part("ala_der", (p) => ala("ala_der", p));

// La pose de reposo tiene que ser idéntica al dibujo base (lo comprueba `pxcli anim check`).
rest(() => {
  draw("ala_izq");
  draw("ala_der");
  draw("cuerpo");
});

// Una función por acción: dibuja el frame f desde cero. t va de 0 a 1.
// Frames: abiertas hacia delante, en medio (rápido), recogidas atrás, en medio (rápido).
action("aleteo", { frames: 4, fps: 15, loop: true }, (f, { t }) => {
  const poses = [
    { giro: 0.35, escala: 0.95 },
    { giro: 0, escala: 1, tramado: true },
    { giro: -0.3, escala: 0.85 },
    { giro: 0, escala: 1, tramado: true },
  ];
  const p = poses[f];
  const bote = f === 2 ? -1 : 0;
  move(0, bote, () => {
    draw("ala_izq", p);
    draw("ala_der", p);
    draw("cuerpo");
  });
});

